def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    y = np.asarray(history, dtype=float)
    y = y[np.isfinite(y)]
    h = max(0, int(horizon))
    if h == 0:
        return []
    if len(y) == 0:
        return [0.0] * h
    if len(y) < 12:
        return [float(y[-1])] * h
    scale = float(np.median(np.abs(y - np.median(y))))
    scale = max(scale, 1e-9)
    candidates = []
    max_p = min(60, len(y) // 3)
    for p in range(4, max_p + 1):
        for cycles in (2, 3, 5, 8):
            if cycles * p > len(y):
                continue
            errors = []
            start = max(p * 2, len(y) - min(4 * p, 40))
            for t in range(start, len(y)):
                vals = []
                for k in range(1, cycles + 1):
                    j = t - k * p
                    if j >= 0:
                        vals.append(float(y[j]))
                if vals:
                    pred = float(np.median(vals))
                    errors.append(abs(pred - float(y[t])))
            if errors:
                candidates.append((float(np.median(errors)) + 0.15 * float(np.mean(errors)), p, cycles))
    baseline = float(np.median(np.abs(y[-min(20, len(y)):] - np.median(y[-min(20, len(y)):]))))
    if not candidates:
        return [float(y[-1])] * h
    score, p, cycles = min(candidates)
    if score > max(2.5 * scale, 2.5 * baseline, 1e-9):
        return [float(np.median(y[-min(7, len(y)):]))] * h
    out = []
    extended = list(map(float, y))
    for _ in range(h):
        t = len(extended)
        vals = [extended[t - k * p] for k in range(1, cycles + 1) if t - k * p >= 0]
        pred = float(np.median(vals)) if vals else float(extended[-1])
        if not np.isfinite(pred):
            pred = float(y[-1])
        out.append(pred)
        extended.append(pred)
    return out

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    y = np.asarray(history, dtype=float)
    y = y[np.isfinite(y)]
    h = max(0, int(horizon))
    if h == 0:
        return []
    if len(y) == 0:
        return [0.0] * h
    if len(y) < 24:
        return [float(y[-1])] * h
    best = None
    max_p = min(60, len(y) // 4)
    for p in range(4, max_p + 1):
        hold = min(2 * p, len(y) // 3)
        train = y[:-hold]
        test = y[-hold:]
        for cycles in (3, 5, 8):
            preds = []
            for j in range(hold):
                t = len(train) + j
                phase_vals = []
                for k in range(1, cycles + 1):
                    idx = t - k * p
                    if idx >= 0:
                        phase_vals.append(float(y[idx]))
                if len(phase_vals) >= 2:
                    slopes = []
                    chronological = phase_vals[::-1]
                    for a in range(len(chronological)):
                        for b in range(a + 1, len(chronological)):
                            slopes.append((chronological[b] - chronological[a]) / (b - a))
                    slope = float(np.median(slopes)) if slopes else 0.0
                    slope = float(np.clip(slope, -0.5 * np.std(train), 0.5 * np.std(train)))
                    pred = float(np.median(phase_vals[:min(3, len(phase_vals))]) + 0.35 * slope)
                elif phase_vals:
                    pred = phase_vals[0]
                else:
                    pred = float(train[-1])
                preds.append(pred)
            score = float(np.median(np.abs(np.asarray(preds) - test)) + 0.2 * np.mean(np.abs(np.asarray(preds) - test)))
            item = (score, p, cycles)
            if best is None or item < best:
                best = item
    if best is None:
        return [float(y[-1])] * h
    _, p, cycles = best
    out = []
    for j in range(h):
        t = len(y) + j
        vals = []
        positions = []
        for k in range(1, cycles + 1):
            idx = t - k * p
            if idx < len(y) and idx >= 0:
                vals.append(float(y[idx]))
                positions.append(-k)
            elif idx >= len(y):
                vals.append(float(out[idx - len(y)]))
                positions.append(-k)
        if len(vals) >= 3:
            slopes = []
            for a in range(len(vals)):
                for b in range(a + 1, len(vals)):
                    den = positions[b] - positions[a]
                    if den != 0:
                        slopes.append((vals[b] - vals[a]) / den)
            slope = float(np.median(slopes)) if slopes else 0.0
            center = float(np.median(vals[:min(3, len(vals))]))
            pred = center + 0.25 * slope
        elif vals:
            pred = float(np.median(vals))
        else:
            pred = float(y[-1])
        lo, hi = np.percentile(y[-min(len(y), 8 * p):], [1, 99])
        margin = max(float(hi - lo), 1.0) * 0.25
        pred = float(np.clip(pred, lo - margin, hi + margin))
        if not np.isfinite(pred):
            pred = float(y[-1])
        out.append(pred)
    return out
